import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../services/api";

export default function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [modules, setModules] = useState([]);
  const [selectedModule, setSelectedModule] = useState("");
  const [error, setError] = useState("");

  const loginUser = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const res = await api.post("/auth/login", { email, password });
      localStorage.setItem("token", res.data.token);
      localStorage.setItem("user", JSON.stringify(res.data.user));
      setModules(res.data.modules);

      // Auto-redirect if only 1 module
      if (res.data.modules.length === 1) {
        navigate(res.data.modules[0].module_path);
      }
    } catch (err) {
      setError(err.response?.data?.message || "Login failed");
    }
  };

  const enterModule = () => {
    if (!selectedModule) return alert("Please select a module");
    navigate(selectedModule);
  };

  return (
    <div className="d-flex justify-content-center align-items-center vh-100">
      {modules.length === 0 ? (
        <form onSubmit={loginUser} className="p-4 border rounded bg-white" style={{ width: "350px" }}>
          <h3 className="text-center mb-3">Login</h3>
          {error && <p className="text-danger">{error}</p>}
          <input
            type="email"
            className="form-control mb-2"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            className="form-control mb-2"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button type="submit" className="btn btn-primary w-100">Login</button>
        </form>
      ) : (
        <div className="p-4 border rounded bg-white" style={{ width: "350px" }}>
          <h4 className="text-center mb-3">Select Module</h4>
          <select className="form-control mb-2" onChange={(e) => setSelectedModule(e.target.value)}>
            <option value="">-- Choose Module --</option>
            {modules.map((m) => (
              <option key={m.module_id} value={m.module_path}>{m.module_name}</option>
            ))}
          </select>
          <button className="btn btn-success w-100" onClick={enterModule}>Enter Module</button>
        </div>
      )}
    </div>
  );
}
